using Flagship.Builder;
using Xunit;
namespace Flagship.Builder.Tests;
public sealed class NativeIsoRemasterTests
{
 [Theory][InlineData(@"C:\Users\x\out.iso","/c/Users/x/out.iso")][InlineData("D:/tmp/seed","/d/tmp/seed")][InlineData(@"relative\dir\f.cfg","relative/dir/f.cfg")]
 public void ConvertsPaths(string input,string expected)=>Assert.Equal(expected,NativeIsoRemaster.ToXorrisoDiskPath(input));
 [Theory][InlineData("Debian 13.5.0 amd64 1",IsoFamily.Debian)][InlineData("/install.amd\n/boot",IsoFamily.Debian)][InlineData("Ubuntu based on Debian\n/casper",IsoFamily.Other)][InlineData("custom",IsoFamily.Other)]
 public void Classifies(string input,IsoFamily expected)=>Assert.Equal(expected,NativeIsoRemaster.ClassifyIsoText(input));
 [Fact]public void SpeechAutobootGoesToThePlainInstaller(){const string x="timeout 300\nontimeout /install.amd/vmlinuz vga=788 initrd=/install.amd/gtk/initrd.gz speakup.synth=soft --- quiet \n";var o=NativeIsoRemaster.EditIsolinuxForPreseed(x);Assert.Contains("ontimeout install",o);Assert.DoesNotContain("ontimeout /install.amd",o);Assert.Contains("timeout 1",o);Assert.Equal(o,NativeIsoRemaster.EditIsolinuxForPreseed(o));}
 [Fact]public void DebianTransforms(){const string g="set timeout=10\nset timeout_style=hidden\nlinux /install.amd/vmlinuz ---\nlinux /install.amd/gtk/vmlinuz ---\n";const string i="prompt 1\ntimeout 600\nappend initrd=/install.amd/initrd.gz ---\n";var go=NativeIsoRemaster.EditGrubForPreseed(g);var io=NativeIsoRemaster.EditIsolinuxForPreseed(i);Assert.Equal(2,go.Split(NativeIsoRemaster.DebianPreseedCommandLine).Length-1);Assert.Contains("set timeout_style=menu",go);Assert.Contains("timeout 1",io);Assert.Contains("prompt 0",io);Assert.Equal(go,NativeIsoRemaster.EditGrubForPreseed(go));Assert.Equal(io,NativeIsoRemaster.EditIsolinuxForPreseed(io));}
 [Theory][InlineData(@"C:\Users\x\out.iso","/cygdrive/c/Users/x/out.iso")][InlineData("D:/tmp/seed","/cygdrive/d/tmp/seed")]
 public void ConvertsPathsForTheBundledXorriso(string input,string expected)=>Assert.Equal(expected,NativeIsoRemaster.ToXorrisoDiskPath(input,true,true));
 [Fact]public async Task AWorkFolderWithReadOnlyFilesIsDeleted(){var root=Path.Combine(Path.GetTempPath(),"remaster-test-"+Guid.NewGuid().ToString("N"));var work=Path.Combine(root,NativeIsoRemaster.WorkDirPrefix+"x");Directory.CreateDirectory(Path.Combine(work,"install.amd"));var f=Path.Combine(work,"install.amd","initrd.gz");File.WriteAllText(f,"x");File.SetAttributes(f,FileAttributes.ReadOnly);Assert.True(await NativeIsoRemaster.DeleteTreeAsync(work));Assert.False(Directory.Exists(work));Directory.Delete(root,true);}
 [Fact]public async Task OnlyStaleWorkFoldersAreSwept(){var root=Path.Combine(Path.GetTempPath(),"remaster-sweep-"+Guid.NewGuid().ToString("N"));var old=Path.Combine(root,NativeIsoRemaster.WorkDirPrefix+"old");var fresh=Path.Combine(root,NativeIsoRemaster.WorkDirPrefix+"fresh");var other=Path.Combine(root,"other-old");foreach(var d in new[]{old,fresh,other})Directory.CreateDirectory(d);Directory.SetLastWriteTimeUtc(old,DateTime.UtcNow.AddDays(-2));Directory.SetLastWriteTimeUtc(other,DateTime.UtcNow.AddDays(-2));NativeIsoRemaster.SweepStaleWorkDirs(root,TimeSpan.FromHours(6));for(var i=0;i<20&&Directory.Exists(old);i++)await Task.Delay(50);Assert.False(Directory.Exists(old));Assert.True(Directory.Exists(fresh));Assert.True(Directory.Exists(other));Directory.Delete(root,true);}
 [Fact]public void OnlyAnMsys2InstallUsesTheRootPrefix(){var root=Path.Combine(Path.GetTempPath(),"msys-"+Guid.NewGuid().ToString("N"));var bin=Path.Combine(root,"usr","bin");Directory.CreateDirectory(bin);var tool=Path.Combine(bin,"xorriso.exe");Assert.True(NativeIsoRemaster.UsesCygdrivePrefix(tool));Directory.CreateDirectory(Path.Combine(root,"etc"));File.WriteAllText(Path.Combine(root,"etc","fstab"),"none / cygdrive binary 0 0\n");Assert.False(NativeIsoRemaster.UsesCygdrivePrefix(tool));Directory.Delete(root,true);}
}